INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66525477', 66525477, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultansi Penyusunan Dokumen Analisis Pendanaan dan Pembiayaan Proyek Prioritas dan Strategis Nasional Bidang Infrastruktur', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 225000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Merumuskan model penguatan kapasitas pemerintah daerah dan rekomendasi kebijakan pendukung dari pemerintah pusat untuk memperluas akses dan efektivitas pembiayaan pembangunan', '"1. Analisis efisiensi investasi publik melalui perhitungan ICOR daerah untuk menilai efektivitas investasi pemerintah daerah terhadap pertumbuhan ekonomi dan output pembangunan; 2. Analisis kemandirian fiskal daerah, dengan mengukur kemampuan daerah dalam membiayai pembangunan dari sumber pendapatan sendiri dan tingkat ketergantungan terhadap transfer pusat; 3. Identifikasi potensi dan bentuk inovasi pendanaan proyek infrastruktur prioritas dan strategis di luar APBN dan APBD, termasuk keterlibatan BUMN, BUMD, dan pihak ketiga dalam skema pembiayaan seperti KPBU, green finance, blended finance, dana CSR, dan lain-lain; 4. Penilaian kesiapan pemerintah daerah dalam mengembangkan inovasi pendanaan, mencakup aspek kelembagaan, SDM, regulasi, dan kapasitas perencanaan pembiayaan infrastruktur; 5. Identifikasi kebutuhan dukungan dari pemerintah pusat untuk memperkuat kapasitas daerah dalam penerapan inovasi pendanaan, baik berupa kebijakan, asistensi teknis, maupun fasilitasi kemitraan pendanaan; 6. Perumusan rekomendasi dan model penguatan kapasitas pemerintah pusat dan daerah dalam inovasi pendanaan infrastruktur dasar berkelanjutan untuk mendukung pencapaian target pembangunan RPJMN 2025–202', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2790570);
