INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66525431', 66525431, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultansi Kajian Inovasi Pendanaan Pembangunan Proyek Prioritas dan Strategis Nasional dalam RPJMN 2025-2029 Bidang Ekonomi Hijau', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 275400000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Penyusunan rekomendasi kebijakan pendanaan proyek pembangunan berbasis perdagangan karbon', '"1. Identifikasi isu strategis dan praktik baik perdagangan karbon dalam negeri dan internasional, untuk mengetahui tantangan dan pembelajaran dari perdagangan karbon yang sudah berjalan baik di pasar dalam negeri maupun internasional. 2. Identifikasi stakeholder dan analisa kelembagaan perdagangan karbon, untuk mengetahui kondisi terkini stakeholder dan kelembagaan terkait perdagangan karbon sehingga dapat disusun rekomendasi kelembagaan yang diperlukan untuk peningkatan akses pendanaan melalui perdagangan karbon. 3. Identifikasi proyek prioritas dan strategis nasional pendukung pengembangan ekonomi hijau yang dapat didukung oleh pendanaan melalui perdagangan karbon 4. Analisa gap kebijakan dan regulasi perdagangan karbon, untuk mengetahui Kebijakan dan regulasi apa saja yang berlaku dan yang diperlukan untuk mendukung terlaksananya pendanaan inovatif berbasis perdagangan karbon. 5. Analisa model bisnis proyek pendukung pengembangan ekonomi hijau yang dapat didukung oleh pendanaan melalui perdagangan karbon, untuk menentukan skema model bisnis yang dapat diterapkan pada proyek berbasis perdagangan karbon. 6. Analisa kebutuhan dukungan pemerintah terhadap proyek berbasis perdagangan karbon 7. Penyusunan rekomendasi kebijakan pendanaan proyek pembangunan berbasis perdagangan karbon', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2790798);
