INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66525722', 66525722, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jamuan Perayaan Natal Bappenas', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 143095650, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', '"Penyelenggaraan Natal Bersama Kementerian PPN/Bappenas Tahun 2025 bertujuan untuk: Memperkuat pembinaan rohani serta nilai moral dan integritas pegawai Kementerian PPN/Bappenas. Menumbuhkan kebersamaan, solidaritas, dan semangat kekeluargaan di lingkungan Kementerian PPN/Bappenas. Menghadirkan kepedulian sosial melalui program donasi kemanusiaan bagi masyarakat terdampak bencana. Memaknai Natal sebagai sumber pengharapan dan pemulihan yang selaras dengan nilai-nilai pelayanan publik dan pembangunan nasional.', 'Pelaksanaan Ibadah Natal Bersama bagi pegawai Kristen/Katolik Kementerian PPN/Bappenas dan tamu undangan. Pelaksanaan Perayaan dan Ramah Tamah Natal sebagai wadah kebersamaan pegawai dan undangan. Pelaksanaan Program Kepedulian Sosial “Kasih untuk Negeri”, berupa pengumpulan dan penyaluran donasi kemanusiaan. Koordinasi teknis dan administratif terkait undangan, keprotokolan, pengaturan peserta, serta dukungan logistik kegiatan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2790825);
