INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66525564', 66525564, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Pengadaan Jasa Konsultansi Penyusunan Dokumen Analisis Pendanaan dan Pembiayaan Pembangunan Lingkungan Berkelanjutan untuk Proyek Prioritas dan Strategis Nasional', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 96000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'rekomendasi kebijakan dan skema pendanaan dan pembiayaan sektor lingkungan dan sistem persampahan didukung dengan perbaikan regulasi', '1) Mengumpulkan dan menganalisis data proyek prioritas dan strategis nasional bidang pembangunan lingkungan dalam RPJMN 2025–2029, termasuk sektor persampahan, air limbah, drainase, sanitasi, dan permukiman berkelanjutan. 2) Menganalisis kebutuhan pendanaan dan pembiayaan proyek lingkungan, termasuk estimasi kebutuhan investasi, sumber pendanaan yang tersedia, serta kesenjangan pembiayaan antara kebutuhan dan kapasitas fiskal pemerintah. 3) Mengkaji penerapan skema Kerja Sama Pemerintah dengan Badan Usaha (KPBU) pada proyek-proyek lingkungan dan permukiman, dengan menelaah kesiapan proyek, struktur pembiayaan, serta faktor-faktor yang memengaruhi pencapaian financial close. 4) Menganalisis struktur pendapatan dan dukungan pemerintah pada proyek lingkungan, termasuk tarif layanan, tipping fee, availability payment, serta bentuk dukungan fiskal pusat dan daerah yang diperlukan agar proyek layak dibiayai. 5) Menganalisis pembagian risiko proyek KPBU sektor lingkungan dan permukiman, mencakup risiko konstruksi, permintaan, operasional, regulasi, dan fiskal, untuk memastikan alokasi risiko yang jelas dan proporsional. 6) Mengkaji kesiapan pembiayaan (financing readiness) proyek lingkungan, termasuk kesiapan dokumen, kepastian kontrak, dukungan kebijakan, dan kesesuaian proyek dengan kebutuhan investor dan lembaga pembiayaan. 7) Mengidentifikasi peluang inovasi pendanaan lingkungan berkelanjutan, seperti blended finance, pembiayaan berbasis kinerja lingkungan, pembiayaan hijau, dan kemitraan publik–swasta, untuk meningkatkan keterlibatan pembiayaan swasta. 8) Menyusun rekomendasi sistem pembiayaan sektor lingkungan atau sistem Pembiayaan persampahan didukung dengan perbaikan regulasi. 9) Menyusun rekomendasi kebijakan dan opsi skema pendanaan yang operasional dan aplikatif untuk mempercepat penyiapan proyek KPBU lingkungan yang bankable, mendukung pencapaian target RPJMN 2025–2029, dan meningkatkan keberlanjutan pembangunan lingkungan nasional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2791809);
