INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66530190', 66530190, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Paket Meeting Fullboard Luar Kota Workshop Kearsipan', 'Jasa Lainnya', 'Dikecualikan', 'Jawa Barat, Bandung (Kota)', 2012000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '( 2, OP, @ 1006000 )', '1. Paket Meeting Fullboard Luar Kota ( 2, OP, @ 1006000 );', 'Penyediaan paket pertemuan fullboard (rapat menginap) guna mendukung pelaksanaan kegiatan dinas bagi peserta dan panitia dengan standar fasilitas yang memadai. Lingkup pekerjaan mencakup penyediaan ruang pertemuan yang dilengkapi dengan sarana pendukung rapat standar, akomodasi penginapan (kamar) dengan kapasitas hunian sesuai ketentuan kelas jabatan dan perjalanan dinas bagi ASN (termasuk sarapan), serta penyediaan konsumsi berupa makan siang, makan malam, dan kudapan (snack) selama durasi kegiatan. Kualitas layanan, fasilitas hotel, dan penyajian menu boga disesuaikan dengan kebutuhan teknis penyelenggaraan serta ketersediaan sarana di lokasi kegiatan, dengan tetap mengacu pada batasan pagu Standar Biaya Masukan (SBM) Paket Fullboard yang berlaku pada tahun anggaran berjalan. Pembayaran dilaksanakan berdasarkan realisasi volume pemakaian nyata (jumlah peserta dan durasi hari) yang didukung dengan bukti pertanggungjawaban serta administrasi perpajakan yang sah sesuai ketentuan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2794701);
