INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66528494', 66528494, 'analyze_legacy', 'Kementerian Energi Dan Sumber Daya Mineral', 'central', 'SEKRETARIAT JENDERAL KEMENTERIAN ENERGI DAN SUMBER DAYA MINERAL', 'Layanan Contact Center Kementerian ESDM', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1336636000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Contact Center ESDM 136 berperan sebagai garda terdepan dalam layanan penyediaan informasi dan penanganan keluhan yang ada di sektor ESDM juga terkait Badan Usaha Milik Negara (BUMN) yang berada di bawah koordinasi Kementerian ESDM seperti PT PLN, PT Pertamina dan PT PGN. Contact center akan menggunakan layanan jalur telepon. Contact Center ESDM 136 tidak menggantikan fungsi contact center PLN123, Pertamina 1500-000 dan PGN yang telah ada selama ini. Ini justru akan memperkuat keberadaan contact center tersebut. Untuk keluhan dan pengaduan pelanggan Listrik, BBM, LPG tetap diutamakan melalui contact center ketiga BUMN tersebut.', 'Contact Center melingkupi aspek yang berhubungan dengan permohonan informasi, termasuk di dalamnya adalah tenaga pelayan informasi (telephoni agent/agen), dukungan teknis (technical support) dan knowledge base yang akan mempermudah pemberian informasi yang dibutuhkan masyarakat. Knowledge base dirancang untuk memiliki kemampuan untuk melakukan komputasi dan penyimpanan pengetahuan. Knowledge base diimplementasikan untuk membantu menjawab pertanyaan–pertanyaan dengan cepat. Hal ini karena pengetahuan telah disimpan terlebih dahulu ke dalam Knowledge Based. Kecepatan dalam melakukan pelayanan juga menjadi indikator baik buruknya pelayanan informasi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2794879);
