INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66530188', 66530188, 'analyze_legacy', 'Badan Pengawas Obat Dan Makanan', 'central', 'INSPEKTORAT UTAMA BADAN POM', 'Diklat mandiri auditor', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Pusat (Kota)', 17726000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '4 Paket', 'Paket menyesuaikan detil dari penyedia', 'Pekerjaan ini mencakup penyelenggaraan pengembangan kompetensi bagi pejabat fungsional auditor maupun fungsional lain di lingkungan Inspektorat I melalui keikutsertaan dalam pendidikan dan pelatihan (diklat) yang diselenggarakan oleh lembaga penyelenggara terpercaya, baik dari unsur instansi pembina, organisasi profesi, maupun lembaga pendidikan terakreditasi lainnya. Spesifikasi teknis pekerjaan meliputi pelaksanaan kegiatan yang dapat dilakukan secara daring melalui platform virtual, luring melalui tatap muka langsung, maupun metode hybrid sesuai dengan kebutuhan efisiensi dan jadwal kedinasan. Materi diklat difokuskan pada penguatan kapabilitas pengawasan intern, audit berbasis risiko, audit teknologi informasi, serta tata kelola sektor publik yang relevan dengan tugas dan fungsi auditor di lingkungan instansi. Seluruh proses pelaksanaan harus didukung oleh instruktur atau narasumber ahli yang kompeten di bidangnya, dengan luaran wajib berupa sertifikat keikutsertaan atau kelulusan resmi yang mencantumkan jumlah jam pelajaran (JP) sebagai bukti valid untuk pemenuhan angka kredit jabatan fungsional.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2795434);
