INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66495464', 66495464, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'BALAI BESAR METEOROLOGI KLIMATOLOGI DAN GEOFISIKA WILAYAH II', 'Pengiriman AWOS Portable, Mobil Double Cabin dan Komputer', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 255359000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '7 Paket', 'Pengiriman Kendaraan Roda 4 Teknis Airside (Toyota Hilux Double Cabin) 1. Jakarta - Stasiun Meteorologi Kelas III Nabire, Papua Tengah 2. Jakarta - Stasiun Meteorologi Kelas III Oesman Sadik Halmahera Selatan, Maluku Utara 3. Jakarta - Stasiun Meteorologi Kelas III Maimun Saleh Sabang, Aceh 4. Jakarta - Stasiun Meteorologi Kelas III Mathilda Batlayeri Maluku Tenggara Barat, Maluku 5. Jakarta - Stasiun Meteorologi Kelas III Tardamu Sabu Raijua, Nusa Tenggara Timur 6. Jakarta - Stasiun Meteorologi Kelas II Silangit Tapanuli Utara, Sumatera Utara 7. Jakarta - Stasiun Meteorologi Kelas III F.L. Tobing Tapanuli Tengah, Sumatera Utara', 'Pengiriman kendaraan dinas bermotor roda empat melibatkan proses dari pusat ke berbagai lokasi dinas, menggunakan metode transportasi darat, laut, atau udara. Prosedur pengiriman mencakup penerimaan kendaraan dengan pengecekan kondisi dan dokumentasi, pengemasan jika diperlukan, serta transportasi yang aman dengan sistem pelacakan untuk memantau status pengiriman secara real-time. Setelah tiba di tujuan, kendaraan akan diperiksa kondisinya sebelum diserahkan kepada penerima. Dokumentasi yang diperlukan termasuk surat jalan, kartu kendaraan, dan polis asuransi untuk perlindungan selama pengiriman. Keamanan kendaraan dijamin dengan alat pengaman dan asuransi, sementara biaya pengiriman meliputi biaya transportasi, asuransi, dan administrasi. Seluruh proses harus mematuhi peraturan lalu lintas dan regulasi yang relevan, dengan komunikasi yang baik antara penyedia layanan dan pihak penerima untuk memastikan pengiriman berjalan lancar dan sesuai jadwal.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2796710);
